export function writeBatch(firestore: Firestore): WriteBatch {
  firestore = cast(firestore, Firestore);
  ensureFirestoreConfigured(firestore);
  return new WriteBatch(firestore, mutations =>
    executeWrite(firestore, mutations)
  );
}
